(()=>{const previous=shots;shots=function(){previous();const target=shotVideoTarget(),methods=document.querySelector('#shotMethodsPanel'),video=document.querySelector('#shotVideoPanel');if(!target||!methods||!video)return;const card=video.closest('.card'),mode=ShotMethods.method(target);if(!card)return;const timeline=card.querySelector('.shot-timeline');if(timeline)timeline.after(methods);else{const head=card.querySelector('.preview-head');if(head)head.after(methods);else card.prepend(methods);}const refs=card.querySelector('.shot-reference-grid');if(refs){const group=document.createElement('section');group.id='shotVideoReferenceSection';const before=refs.previousElementSibling;if(before?.id==='selectedReferenceHint'){const intro=before.previousElementSibling,title=intro?.previousElementSibling;if(title?.tagName==='B')group.append(title);if(intro?.tagName==='P')group.append(intro);group.append(before);}else{const title=before?.previousElementSibling;if(title?.tagName==='B')group.append(title);if(before?.tagName==='P')group.append(before);}group.append(refs);const exportButton=document.querySelector('#hierarchyBindings');if(exportButton)group.append(exportButton);const select=document.querySelector('#shotMethodChoice'),recommendation=select?.closest('label')?.nextElementSibling;if(recommendation)recommendation.after(group);else methods.prepend(group);group.hidden=mode!=='reference_images';group.style.display=group.hidden?'none':'block';}
const frame=methods.querySelector('[data-frame-card]')?.parentElement,size=document.querySelector('#shotFrameSize')?.closest('label');if(mode==='reference_images'){if(frame){const details=frame.closest('details');if(details)details.style.display='none';else frame.style.display='none';}if(size)size.style.display='none';}else{if(frame)frame.style.display='grid';if(size)size.style.display='';const first=methods.querySelector('[data-frame-card=first]'),last=methods.querySelector('[data-frame-card=last]');if(first)first.style.display='';if(last)last.style.display=mode==='first_frame'?'none':'';}};render();})();
